<?php
namespace App\Services;
use App\Models\{RoomType,Room,Guest,User,Reservation,RestaurantOrder,MenuItem,DiningTable,Setting,Payment,AuditEntry};
class OriginalSnapshot {
 public static function make(?User $user):array {
  $staff=$user&&$user->role!=='guest';$admin=$user?->role==='admin';$hotel=$staff&&in_array($user->role,['admin','frontdesk','housekeeping']);$restaurant=$staff&&in_array($user->role,['admin','restaurant']);
  $types=RoomType::withCount('rooms')->get()->map(fn($t)=>['id'=>$t->id,'n'=>$t->name,'r'=>(float)$t->rate,'g'=>$t->capacity,'c'=>$t->rooms_count,'b'=>101,'desc'=>$t->description,'bed_size'=>$t->bed_size,'photo'=>$t->photo,'extra_capacity'=>$t->extra_capacity,'extra_person_rate'=>(float)$t->extra_person_rate,'accessible_room'=>$t->accessible_room,'accessible_bathroom'=>$t->accessible_bathroom,'amenities'=>['Wi-Fi','Air conditioning','Private bathroom','Smart TV']])->all();
  $rooms=$hotel?Room::with('type')->get()->map(fn($r)=>['id'=>$r->id,'n'=>(int)$r->number,'t'=>$r->type->name,'floor'=>$r->floor,'accessible_room'=>$r->accessible_room,'accessible_bathroom'=>$r->accessible_bathroom,'out_of_service'=>$r->out_of_service,'status'=>$r->out_of_service?'Maintenance':'Available'])->all():[];
  $hk=$hotel?Room::get()->mapWithKeys(fn($r)=>[$r->number=>['s'=>$r->housekeeping_status,'p'=>'','a'=>0,'assignedName'=>'']])->all():[];
  $res=[];
  if($user){$b=Reservation::with('guest','type','room','charges','payments');if($user->role==='guest')$b->where('guest_id',$user->guest_id);if($user->role==='restaurant')$b->where('status','Checked-in');if($user->role==='housekeeping')$b->where('status','Checked-in');
   foreach($b->get() as $r){$f=HotelService::folio($r);$private=$hotel||$user->role==='guest';$nights=max(1,(int)\Carbon\Carbon::parse($r->arrival)->diffInDays($r->departure));$res[]=['id'=>$r->id,'c'=>$r->code,'g'=>$r->guest->name,'email'=>$private?$r->guest->email:'','ph'=>$private?$r->guest->phone:'','guestId'=>$r->guest_id,'payerId'=>$r->payer_guest_id,'t'=>$r->type?->name??$r->room?->type?->name,'typeId'=>$r->room_type_id,'n'=>$r->room?(int)$r->room->number:0,'i'=>$r->arrival,'o'=>$r->departure,'gu'=>$r->guest_count,'adults'=>$r->adults,'children'=>$r->children,'st'=>$r->status,'note'=>$r->requests,'source'=>$r->source,'requires_accessible_room'=>$r->requires_accessible_room,'rt'=>$private?round($r->amount/$nights,2):0,'created'=>$r->created_at->toDateString(),'total'=>$private?$f['total']:0,'balanceDue'=>$private?$f['balance']:0,'depositPaid'=>$private?$f['paid']:0,'depositRequired'=>0,'p'=>$f['balance']<=0?'Paid':($f['paid']>0?'Partial':'Unpaid'),'m'=>'','breakfast'=>$r->breakfast,'breakfast_pax'=>$r->breakfast_pax,'pricing'=>$private?$r->pricing:null,'pay'=>$private?$r->payments->map(fn($p)=>['id'=>$p->receipt,'or'=>$p->receipt,'a'=>(float)$p->amount,'amt'=>(float)$p->amount,'k'=>$p->kind,'t'=>$p->kind,'m'=>$p->method,'date'=>$p->created_at->toDateString(),'at'=>$p->created_at->toIso8601String(),'cashier'=>$p->created_by,'postingLocation'=>$p->posting_location])->all():[],'x'=>$private?$r->charges->map(fn($c)=>['id'=>$c->id,'desc'=>$c->description,'amt'=>(float)$c->amount,'cat'=>'Incidentals','date'=>$c->created_at->toDateString(),'reversal_of'=>$c->reversal_of])->all():[]];}
  }
  $orders=[];if($restaurant||$user?->role==='guest'){
   $b=RestaurantOrder::with('items');if(!$restaurant)$b->whereIn('delivery_reservation_id',Reservation::where('guest_id',$user->guest_id)->select('id'));
   $orders=$b->get()->map(function($o){$delivery=Reservation::with('room')->find($o->delivery_reservation_id);$r=Reservation::find($o->reservation_id);return ['id'=>$o->id,'code'=>$o->code,'type'=>$o->channel==='Room service'?'In-room':'Dine-in','target'=>$o->channel==='Room service'?'Room '.($delivery?->room?->number??''):$o->table_label,'table'=>$o->dining_table_id,'tableNo'=>$o->dining_table_id,'room'=>$delivery?->room?(int)$delivery->room->number:null,'resCode'=>$r?->code??$delivery?->code,'linkedRes'=>$r?->code??$delivery?->code,'subtotal'=>(float)$o->amount,'status'=>$o->status==='Void'?'Cancelled':($o->status==='Settled'?'Paid':'New'),'payStatus'=>$o->status==='Void'?'Void':($o->settlement==='Room'?'Room folio':($o->status==='Settled'?'Paid':'Unpaid')),'paymentKind'=>$o->settlement,'service_status'=>$o->service_status,'created'=>$o->created_at->toDateString(),'createdAt'=>$o->created_at->toIso8601String(),'lines'=>$o->items->map(fn($i)=>['id'=>$i->menu_item_id,'menuId'=>$i->menu_item_id,'name'=>$i->name,'qty'=>$i->quantity,'price'=>(float)$i->unit_price,'unitPrice'=>(float)$i->unit_price])->all()];})->all();
  }
  $guestRows=$hotel?Guest::get():($user?Guest::whereKey($user->guest_id)->get():collect());
  $guests=$guestRows->map(fn($g)=>['id'=>$g->id,'name'=>$g->name,'email'=>$g->email,'phone'=>$g->phone,'address'=>$g->address,'birthDate'=>$g->birth_date,'created'=>$g->created_at->toDateString()])->all();
  $roleMap=['admin'=>'superadmin','frontdesk'=>'hotel_receptionist','restaurant'=>'restaurant_receptionist','housekeeping'=>'hotel_receptionist'];
  $session=$user?['id'=>$user->id,'name'=>$user->name,'email'=>$user->email,'role'=>$roleMap[$user->role]??'guest','department'=>$user->role==='restaurant'?'Restaurant':($user->role==='housekeeping'?'Housekeeping':'Front Desk'),'guestId'=>$user->guest_id]:null;
  $data=['types'=>$types,'rooms'=>$rooms,'hk'=>$hk,'res'=>$res,'orders'=>$orders,'guestProfiles'=>$guests,'guests'=>$guests,'guestAccounts'=>$guests,'menu'=>MenuItem::get()->map(fn($m)=>['id'=>$m->id,'name'=>$m->name,'category'=>$m->category,'price'=>(float)$m->price,'available'=>(bool)$m->available,'desc'=>$m->description,'description'=>$m->description,'photo'=>$m->photo?asset($m->photo):null,'photo_credit'=>$m->photo_credit,'photo_source'=>$m->photo_source,'photo_license'=>$m->photo_license,'photo_license_url'=>$m->photo_license_url,'station'=>'Kitchen'])->all(),'tables'=>DiningTable::get()->map(fn($t)=>['id'=>$t->id,'num'=>$t->id,'name'=>$t->label,'label'=>$t->label,'seats'=>$t->capacity,'capacity'=>$t->capacity,'area'=>'Main Dining','status'=>$t->status==='Available'?'Free':($t->status==='Occupied'?'Occupied':'Reserved'),'st'=>$t->status==='Available'?'Free':($t->status==='Occupied'?'Occupied':'Reserved')])->all(),'staff'=>$hotel?User::where('role','!=','guest')->when(!$admin,fn($q)=>$q->where('role','housekeeping'))->get()->map(fn($u)=>['id'=>$u->id,'name'=>$u->name,'email'=>$u->email,'role'=>$u->role==='admin'?'Management':($u->role==='restaurant'?'Restaurant Receptionist':($u->role==='housekeeping'?'Housekeeping':'Front Desk')),'department'=>$u->role==='restaurant'?'Restaurant':'Front Desk','active'=>$u->active,'phone'=>$u->phone,'shift'=>'Day'])->all():[],'auditLog'=>$admin?AuditEntry::latest()->limit(500)->get()->map(fn($a)=>['id'=>$a->id,'action'=>$a->action,'entity'=>$a->subject,'recordType'=>$a->subject,'recordId'=>$a->subject,'details'=>json_encode($a->details),'actorName'=>'User '.$a->user_id,'date'=>$a->created_at->toDateString(),'time'=>$a->created_at->format('H:i'),'at'=>$a->created_at->toIso8601String()])->all():[],'promos'=>TrainingPolicy::get()['promos'],'policy'=>TrainingPolicy::get(),'threads'=>[],'inquiries'=>[],'hkRequests'=>[],'maintenance'=>[],'feedback'=>[],'tableRes'=>[],'payments'=>[],'approvalRequests'=>[],'notifications'=>[],'loyaltyLedger'=>[],'bookingHolds'=>[],'paymentIntents'=>[]];
  if(!$admin){$data['promos']=array_values(array_filter($data['promos'],fn($p)=>$p['public']??false));$data['policy']['promos']=$data['promos'];}
  foreach($data['promos'] as &$p){$p['type']='Percent';$p['value']=$p['percent'];$p['active']=true;$p['name']=$p['label'];$p['discount']=$p['percent'];}unset($p);
  if($hotel||$restaurant){$data['businessDate']=BusinessDate::date($user->role==='restaurant'?'Restaurant':'Hotel');}
  foreach(\Illuminate\Support\Facades\DB::table('original_ui_records')->when(!$user,fn($q)=>$q->whereRaw('1=0'))->when($user?->role==='guest',fn($q)=>$q->where('owner_id',$user->id))->when($user?->role==='restaurant',fn($q)=>$q->whereIn('entity',['threads','tableRes']))->get() as $item){if($item->entity==='hkMetadata'&&$hotel){$meta=json_decode($item->data,true);if(isset($data['hk'][$item->record_key]))$data['hk'][$item->record_key]=array_replace($data['hk'][$item->record_key],array_intersect_key($meta,array_flip(['a','p','assignedName'])));}
   if(isset($data[$item->entity]))$data[$item->entity][]=json_decode($item->data,true);}
  foreach($data['types'] as &$t){$photos=config('property-media.rooms.'.strtolower($t['n']),[]);$t['photos']=array_map(fn($p)=>asset($p),$photos);if(!$t['photo']&&$photos)$t['photo']=asset($photos[0]);$meta=Setting::where('key','original_type_'.$t['id'])->first()?->value??[];$t=array_replace($t,$meta);}unset($t);
  $data['amenityPhotos']=array_map(fn($p)=>asset($p),config('property-media.amenities',[]));
  $data['config_overrides']=Setting::where('key','original_ui_config')->first()?->value??[];$data['audit']=$data['auditLog'];$data['hkReq']=$data['hkRequests'];$data['mReq']=$data['maintenance'];
  return ['user'=>$session,'serverRole'=>$user?->role,'data'=>$data];
 }
}
